SELECT ROUND(
  SUM(CASE WHEN (env_metrics->'temperature'->>'excursion_count')::int = 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(*),
  2
) AS cold_chain_compliance_rate_pct
FROM main.environmentalmonitoring;

SELECT 
  ROUND(
    AVG(
      (
        (GREATEST((env_metrics->'temperature'->>'max_c')::real - 8, 0) + 
         GREATEST(2 - (env_metrics->'temperature'->>'min_c')::real, 0)) / 2.0
      ) * ((env_metrics->'temperature'->>'excursion_duration_min')::real / 60.0)
    ), 4
  ) AS avg_temperature_impact_eia
FROM environmentalmonitoring
WHERE (env_metrics->'temperature'->>'excursion_count')::int > 0;

SELECT
  ROUND(AVG(
    (CASE vendSecRate WHEN 'A' THEN 1.0 WHEN 'B' THEN 0.75 WHEN 'C' THEN 0.5 ELSE 0.25 END
     + CASE contrState WHEN 'Active' THEN 1.0 WHEN 'Under Review' THEN 0.5 ELSE 0.0 END) / 2.0
  ), 4) AS vendor_reliability_score
FROM VendorManagement;

SELECT AVG(
  (CASE "vendSecRate" WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 END)
  * (CASE WHEN "contrState" = 'Active' THEN 1 ELSE 0.5 END)
) AS overall_vendor_reliability
FROM VendorManagement;

SELECT AVG(
  (CASE "vendSecRate" WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 END)
  * (CASE WHEN "contrState" = 'Active' THEN 1 ELSE 0.5 END)
) AS avg_vendor_reliability_index
