SELECT AVG(
  (
    (CAST(r.risk3y->'risk_measures_3y'->>'Avg_Return_3Y' AS DOUBLE) - CAST(p.returnmetrics->'benchmark_returns'->>'Bench_Return_3Y' AS DOUBLE))
    / CAST(r.risk3y->'risk_measures_3y'->>'Volatility_3Y' AS DOUBLE)
  )
  *
  (
    (p.histstats->>'Positive_Years')::numeric / NULLIF((p.histstats->>'Positive_Years')::numeric + (p.histstats->>'Negative_Years')::numeric, 0) * 100
  ) / 100
) AS avg_cair
FROM risk_metrics r
JOIN performance p ON p.productref = r.investmentref;

SELECT AVG(
  (
    (CAST(risk3y->'risk_measures_3y'->>'Avg_Return_3Y' AS DOUBLE) - CAST((SELECT p.returnmetrics->'benchmark_returns'->>'Bench_Return_3Y' FROM main.performance p WHERE p.productref = main.risk_metrics.investmentref) AS DOUBLE))
    / CAST(risk3y->'risk_measures_3y'->>'Volatility_3Y' AS DOUBLE)
  )
  *
  (
    (SELECT (p.histstats->>'Positive_Years')::numeric / NULLIF((p.histstats->>'Positive_Years')::numeric + (p.histstats->>'Negative_Years')::numeric, 0) * 100
     FROM main.performance p WHERE p.productref = main.risk_metrics.investmentref)
    / 100
  )
) AS avg_consistency_adjusted_information_ratio
FROM main.risk_metrics;

